1. **`crates/calc-func/src/ported/cashflow_rate_family.rs` (`irr_u_secant` & `irr_kernel`, lines `519–684`)**:
```rust
#[derive(Clone, Copy)]
enum IrrStep { Ok(f64), RetryNum, HardNum, HardDiv0 }

fn irr_u_secant(cashflows: &[f64], u_start: f64) -> IrrStep {
    use crate::ported::excel_numeric::{
        excel_x87_add as add, excel_x87_div as div, excel_x87_mul as mul, excel_x87_sub as sub,
    };
    if !u_start.is_finite() { return IrrStep::RetryNum; }
    let npv = |u: f64| -> Result<f64, IrrStep> {
        let v = sub(1.0, u);
        if v == 0.0 { return Err(IrrStep::HardDiv0); }
        let base = div(1.0, v);
        if !base.is_finite() || base == 0.0 { return Err(IrrStep::HardDiv0); }
        let (mut total, mut power) = (0.0, 1.0);
        for (k, &flow) in cashflows.iter().enumerate() {
            if k > 0 { power = mul(power, base); }
            let divisor = irr_daz(power);
            if !divisor.is_finite() || divisor == 0.0 { return Err(IrrStep::HardDiv0); }
            total = add(total, irr_daz(div(flow, divisor)));
        }
        if total.is_finite() { Ok(total) } else { Err(IrrStep::HardNum) }
    };
    let publish = |u: f64, min_v: f64| -> IrrStep {
        let v = sub(1.0, u);
        if v < min_v { return IrrStep::RetryNum; }
        let rate = crate::ported::real_policy::excel_underflow_to_zero(sub(div(1.0, v), 1.0));
        if rate.is_finite() && rate > -1.0 {
            IrrStep::Ok(if rate == 0.0 { 0.0 } else { rate })
        } else {
            IrrStep::RetryNum
        }
    };
    let is_flat = |chg: f64| (0.0..f64::MIN_POSITIVE / 16.0).contains(&chg);
    let mut before = u_start;
    let mut value_before = match npv(before) { Ok(v) => v, Err(e) => return e };
    let offset = if value_before > 0.0 { -0.001 } else { 0.001 };
    let mut current = add(before, offset);
    let mut value = match npv(current) { Ok(v) => v, Err(e) => return e };
    let mut step = f64::INFINITY;
    for _ in 0..200u32 {
        let mut change = sub(value, value_before);
        if is_flat(change) {
            let nudge = if current > before { 0.001 } else { -0.001 };
            before = add(before, nudge);
            value_before = match npv(before) { Ok(v) => v, Err(e) => return e };
            change = sub(value, value_before);
            if is_flat(change) { return IrrStep::RetryNum; }
        }
        let divisor = irr_daz(change);
        if divisor == 0.0 { return IrrStep::HardDiv0; }
        let numerator = irr_daz(mul(value, sub(current, before)));
        let next = sub(current, div(numerator, divisor));
        if !next.is_finite() { return IrrStep::HardNum; }
        step = sub(next, current).abs();
        (before, value_before) = (current, value);
        current = next;
        value = match npv(current) { Ok(v) => v, Err(e) => return e };
        if step < 1e-7 && value.abs() < 1e-7 { return publish(current, 1e-7); }
    }
    if step <= 1e-4 && value.abs() <= 1e-4 { publish(current, 1e-4) } else { IrrStep::RetryNum }
}
